const input = $input.item.json;

let raw = input;

if (input.content?.[0]?.text) {
  raw = input.content[0].text;
}

if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw);
  } catch (e) {
    raw = { specialist: raw };
  }
}

const specialist =
  raw.specialist ||
  raw.result ||
  raw.name ||
  "General Medicine";

return {
  json: {
    ...$('Vaidya Clinical Engine').item.json,
    specialist: specialist
  }
};

